import{_ as r,a0 as l,w as p,s as d,ao as o,I as a,x as t,a1 as n,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Obsidian 中创建和使用链接 | LCTT x X-CMD","titleTemplate":false,"description":"在 Obsidian 中创建和使用链接 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Obsidian 中创建和使用链接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Obsidian 中创建和使用链接 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20231211 Creating and Working with Links in Obsidian","title":"在 Obsidian 中创建和使用链接","tag":"202401","desc":""},"relativePath":"202401/20231211 Creating and Working with Links in Obsidian.md","filePath":"[post].md"}'),b={name:"202401/20231211 Creating and Working with Links in Obsidian.md"};function g(k,i,u,h,m,f){const s=l("Link");return p(),d("div",null,[i[25]||(i[25]=o('<h1 id="在-obsidian-中创建和使用链接" tabindex="-1">在 Obsidian 中创建和使用链接 <a class="header-anchor" href="#在-obsidian-中创建和使用链接" aria-label="Permalink to “在 Obsidian 中创建和使用链接”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/27/095314xdbbtbjek22bbm8r.jpg" alt=""></p><blockquote><p>Obsidian 知识库工具的真正威力在于链接。学习使用它。</p></blockquote><p>Obsidian 的最大卖点之一是其强大的文档链接和可视化。Obsidian 提供了多种链接文档和图像的方法。我们将逐一介绍。</p><p>你将在 Obsidian 中看到三种内部链接方法：</p><ul><li>拖放方式（简单但有限）</li><li>使用 Markdown 链接</li><li>使用维基链接（广泛且强大）</li></ul><p>我还将分享一些有关使用图表和反向链接的技巧。让我们来看看它。</p><blockquote><p>✋ <strong>非自由和开源软件警告！</strong> Obsidian 不是开源软件，我们知道这一事实。然而，它是一种在编码人员（包括开源开发人员）中非常流行的工具。这就是我们介绍它的原因。</p></blockquote><h3 id="方法-1-通过拖放链接" tabindex="-1">方法 1：通过拖放链接 <a class="header-anchor" href="#方法-1-通过拖放链接" aria-label="Permalink to “方法 1：通过拖放链接”">​</a></h3><p>是的，这是最简单的链接。转到要在其中创建链接的文档。现在，在左侧边栏上，展开该特定文件夹，其中包含目标注释。</p><p>要创建链接，只需将此目标文件拖放到你希望链接显示的位置即可。</p><p><img src="https://itsfoss.com/content/images/2023/12/link-by-drag-and-drop.gif" alt="通过拖放添加链接"></p><p>你可以稍后更改链接文本。</p><h3 id="方法-2-使用-markdown-链接" tabindex="-1">方法 2：使用 Markdown 链接 <a class="header-anchor" href="#方法-2-使用-markdown-链接" aria-label="Permalink to “方法 2：使用 Markdown 链接”">​</a></h3><p>由于 Obsidian 使用 Markdown 作为其核心，因此可以通过输入传统的 Markdown 命令进行链接。</p><p>比方说，你必须在 “Markdown Advanced” 页面中创建一个指向 “Markdown Checklist” 页面的链接。首先，你需要记下要链接到的文件的位置。</p><p>然后，只需添加这一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[链接文本]（文件的相对路径）</span></span></code></pre></div><p>或者，如果你有要链接的文件，并且想要提供系统中的绝对路径，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[链接文本](file://绝对路径)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/12/linking-using-absolute-path.png" alt="使用绝对路径链接"></p>',21)),a("blockquote",null,[a("p",null,[i[1]||(i[1]=t("🚧 如果你 ",-1)),n(s,{href:"https://itsfoss.com/markdown-links/"},{default:e(()=>[...i[0]||(i[0]=[t("使用 Markdown 链接",-1)])]),_:1}),i[2]||(i[2]=t("，请确保文件和文件夹的名称中没有空格，因为这在某些情况下可能会引起一些麻烦。",-1))])]),i[26]||(i[26]=a("h3",{id:"方法-3-使用紧凑型维基链接来链接页面",tabindex:"-1"},[t("方法 3：使用紧凑型维基链接来链接页面 "),a("a",{class:"header-anchor",href:"#方法-3-使用紧凑型维基链接来链接页面","aria-label":"Permalink to “方法 3：使用紧凑型维基链接来链接页面”"},"​")],-1)),a("p",null,[i[5]||(i[5]=t("Obsidian 支持使用 ",-1)),a("ruby",null,[n(s,{href:"https://en.wikipedia.org/wiki/Help:Link"},{default:e(()=>[...i[3]||(i[3]=[t("维基链接",-1)])]),_:1}),i[4]||(i[4]=a("rt",null,"Wikilink",-1))]),i[6]||(i[6]=t(" 来链接页面的直观方式。它们是紧凑的链接并且是交互式链接。默认情况下，此功能处于打开状态。",-1))]),i[27]||(i[27]=o('<p>如果你想知道，是的，它与维基百科有关。他们用它来内部链接他们的维基页面。</p><h4 id="添加内部注释的链接" tabindex="-1">添加内部注释的链接 <a class="header-anchor" href="#添加内部注释的链接" aria-label="Permalink to “添加内部注释的链接”">​</a></h4><p>要创建链接，只需输入 <code>[[</code>。这将启动一个交互式对话框，你可以在其中搜索要链接的文档。</p><p><img src="https://itsfoss.com/content/images/2023/12/add-interactive-wikilinks.gif" alt="添加交互式维基链接"></p><blockquote><p>💡 你可以使用 [[link|要显示的文本]]使自定义文本显示在维基链接上。例如 [[notes/hello.md|这是 Hello 文件的链接]]</p></blockquote><h4 id="添加图像文件" tabindex="-1">添加图像文件 <a class="header-anchor" href="#添加图像文件" aria-label="Permalink to “添加图像文件”">​</a></h4><p>此外，你可以使用此链接方法添加其他文件，例如图像，但在使用 <code>[[</code> 搜索之前需要添加 <code>!</code> 符号。请看下图以了解其实际效果。</p><p><img src="https://itsfoss.com/content/images/2023/12/add-image-using-wikilinks.gif" alt="使用维基链接添加图像"></p><h4 id="添加内部标题链接" tabindex="-1">添加内部标题链接 <a class="header-anchor" href="#添加内部标题链接" aria-label="Permalink to “添加内部标题链接”">​</a></h4><p>有一种方法可以在同一页面的各个标题之间创建内部链接。为此，首先输入 <code>[[</code>，然后使用 Markdown 标题语法和要链接的特定标题的名称。</p><p>例如，如果你打算链接到文档中的第六个标题（2 级标题），请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[[##Paragraph Six</span></span></code></pre></div><p>这将显示在交互式选择中。</p><p><img src="https://itsfoss.com/content/images/2023/12/Link-to-heading-1.gif" alt="链接到标题"></p><blockquote><p>💡 你可以将鼠标悬停在链接上时按 CTRL 键来进行预览。</p></blockquote><h4 id="添加指向文本块的链接" tabindex="-1">添加指向文本块的链接 <a class="header-anchor" href="#添加指向文本块的链接" aria-label="Permalink to “添加指向文本块的链接”">​</a></h4><p>Obsidian 允许你创建指向文档中特定文本块的链接。为此，首先，转到要添加链接的块的最末尾。</p><p>现在，使用 <code>^</code> 符号向该块添加唯一标识符。</p><p><img src="https://itsfoss.com/content/images/2023/12/Add-unique-identifier-to-a-block.png" alt="向块添加唯一标识符"></p><p>现在，你可以通过输入 <code>[[^</code> 来添加到此部分的链接。这将自动提示你可用的块。选择一项并按回车键。</p><p><img src="https://itsfoss.com/content/images/2023/12/your-block-link.gif" alt="添加链接到块"></p><h4 id="维基链接的问题" tabindex="-1">维基链接的问题 <a class="header-anchor" href="#维基链接的问题" aria-label="Permalink to “维基链接的问题”">​</a></h4><p>有时，如果你想要纯 Markdown 文档，并且专注于多个 Markdown 编辑器之间的互操作性，那么维基链接功能可能会产生问题。</p><p>由于这些在 Obsidian 内部工作，因此链接在其他编辑器上显示为损坏。在这种情况下，你可以关闭维基链接。一切都完美无缺，只是链接现在将以 Markdown 格式显示。</p><p>为此，首先选择左下角的设置按钮。</p><p><img src="https://itsfoss.com/content/images/2023/12/click-on-settings-button-in-obsidian.png" alt="点击设置"></p><p>现在，从 “<ruby>文件和链接<rt>Files and Links</rt></ruby>” 选项卡关闭维基链接功能。</p><p><img src="https://itsfoss.com/content/images/2023/12/turn-off-the-wikilink-feature.png" alt="关闭维基链接功能"></p><h4 id="组织附件文件的提示" tabindex="-1">组织附件文件的提示 <a class="header-anchor" href="#组织附件文件的提示" aria-label="Permalink to “组织附件文件的提示”">​</a></h4><p>对于那些在 Obsidian 中附加许多文件的人，建议在每本书下为这些附件创建一个单独的文件夹。</p><p>现在，打开 “<ruby>设置<rt>Settings</rt></ruby> &gt; <ruby>文件和链接<rt>Files and Links</rt></ruby>”。在这里，首先，你需要确保链接路径是相对于文件位置的。然后，将新附件的默认位置设置为 “<ruby>当前文件夹下的子文件夹<rt>Subfolder under current folder</rt></ruby>”。现在，在下一个字段中指定 “<ruby>附件<rt>Attachments</rt></ruby>”，即 “<ruby>子文件夹名称<rt>Subfolder name</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/12/set-attachment-folder-location-and-other-settings-1.png" alt="设置附件文件夹位置"></p><p>就是这样。从现在开始，当你通过复制和粘贴放置任何附件时，它们将自动放置在该笔记文件夹内的“附件”文件夹中。新链接将在任何 Markdown 编辑器之间完美地互操作，因为路径现在是相对于文件位置的。</p><blockquote><p>📋 即使此维基链接功能已关闭，你仍然可以使用 [[ 键以交互方式搜索和添加链接。变化是，现在链接不再是紧凑的，而是长 Markdown 链接。</p></blockquote><p>此外，你还可以打开 “<ruby>自动更新内部链接<rt>Automatically Update Internal Links</rt></ruby>” 按钮，以确保在重命名文件时自动更新链接。</p><h3 id="使用图表和反向链接" tabindex="-1">使用图表和反向链接 <a class="header-anchor" href="#使用图表和反向链接" aria-label="Permalink to “使用图表和反向链接”">​</a></h3><p>创建完链接后，就可以通过链接查看笔记之间的其他笔记之间的关系。单击侧面的图表视图按钮即可进入图表预览。</p><p><img src="https://itsfoss.com/content/images/2023/12/graph-view-in-obsidian.png" alt="Obsidian 中的图表视图"></p><p>正如你所看到的，你将在一个整洁的图表上获得该注释的链接。如果你按空白选项卡上的图表视图，你将获得所有笔记及其关系。</p><p><img src="https://itsfoss.com/content/images/2023/12/part-of-a-graph-view.png" alt="Notes Vault 示例的一些链接示例"></p><p>此外，每个笔记都有一 “传出链接” 和 “传入链接” 选项卡，你可以在其中跟踪相关链接。</p><p><img src="https://itsfoss.com/content/images/2023/12/Links-out-and-in.png" alt="传出和传入链接"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>正如你所看到的，虽然在 Obsidian 中创建指向其他页面的内部链接很简单，但通过维基链接，你可以创建更加个性化和定制的知识库。</p>',44)),a("p",null,[i[8]||(i[8]=t("对于那些不喜欢 Obsidian 闭源性质的人来说，",-1)),n(s,{href:"https://itsfoss.com/logseq/"},{default:e(()=>[...i[7]||(i[7]=[t("Logseq",-1)])]),_:1}),i[9]||(i[9]=t(" 是一个不错的选择。",-1))]),i[28]||(i[28]=a("p",null,[a("em",null,"（题图：DA/57173f4d-5548-471f-8d70-a48e3b5e964a）")],-1)),i[29]||(i[29]=a("hr",null,null,-1)),a("p",null,[i[11]||(i[11]=t("via: ",-1)),n(s,{href:"https://itsfoss.com/obsidian-create-links/"},{default:e(()=>[...i[10]||(i[10]=[t("https://itsfoss.com/obsidian-create-links/",-1)])]),_:1})]),a("p",null,[i[16]||(i[16]=t("作者：",-1)),n(s,{href:"https://itsfoss.com/author/sreenath/"},{default:e(()=>[...i[12]||(i[12]=[t("Sreenath",-1)])]),_:1}),i[17]||(i[17]=t(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[13]||(i[13]=[t("lujun9972",-1)])]),_:1}),i[18]||(i[18]=t(" 译者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:e(()=>[...i[14]||(i[14]=[t("geekpi",-1)])]),_:1}),i[19]||(i[19]=t(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:e(()=>[...i[15]||(i[15]=[t("wxy",-1)])]),_:1})]),a("p",null,[i[22]||(i[22]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[20]||(i[20]=[t("LCTT",-1)])]),_:1}),i[23]||(i[23]=t(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:e(()=>[...i[21]||(i[21]=[t("Linux中国",-1)])]),_:1}),i[24]||(i[24]=t(" 荣誉推出",-1))])])}const C=r(b,[["render",g]]);export{x as __pageData,C as default};
